import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/workforce-duty.json"), "utf8"),
);
const models = emitModels(contract.models, "dutyExchangeKindSchema");
let go =
  '// Code generated by scripts/generate-workforce-duty.mjs; DO NOT EDIT.\npackage workforce\n\nimport("time";"github.com/google/uuid")\n\n';
go += `var dutyExchangeKinds=[]string{${Object.keys(contract.kinds)
  .map((k) => JSON.stringify(k))
  .join(",")}}\n`;
go += `var dutyExchangeStatuses=[]string{${Object.keys(contract.statuses)
  .map((k) => JSON.stringify(k))
  .join(",")}}\n`;
let ts = '// Generated by scripts/generate-workforce-duty.mjs.\nimport { z } from "zod";\n\n';
ts += `export const DUTY_EXCHANGE_KINDS=${JSON.stringify(contract.kinds)} as const;\nexport const dutyExchangeKindSchema=z.enum(${JSON.stringify(Object.keys(contract.kinds))});\n`;
ts += `export const DUTY_EXCHANGE_STATUSES=${JSON.stringify(contract.statuses)} as const;\n`;
await writeGenerated(
  root,
  "backend/internal/modules/workforce/duty_types.go",
  go + models.go,
  "packages/api/src/duty-contract.ts",
  ts + models.ts,
  "duty",
);
